use serde_json::{Value, json};

pub fn solve(input: Value) -> Value {
    let obj = input.as_object().unwrap();
    let n = obj["n"].as_i64().unwrap();
    let start = obj["start"].as_i64().unwrap();
    let edges = obj["edges"].as_array().unwrap();

    let mut graph = vec![vec![]; n as usize];
    for edge in edges {
        let from = edge[0].as_i64().unwrap() as usize;
        let to = edge[1].as_i64().unwrap() as usize;
        graph[from].push(to);
    }

    let mut visited = vec![false; n as usize];
    let mut result = vec![];

    dfs(start as usize, &graph, &mut visited, &mut result);

    result.sort_unstable();
    json!(result)
}

fn dfs(node: usize, graph: &Vec<Vec<usize>>, visited: &mut Vec<bool>, result: &mut Vec<usize>) {
    if visited[node] {
        return;
    }
    visited[node] = true;
    result.push(node as i64);
    for &neighbor in &graph[node] {
        dfs(neighbor, graph, visited, result);
    }
}
